		registration(boundaryRepo, testDigestA, sequenceTag, true, regRetention, regSizeA)),
		http.StatusServiceUnavailable, codeStorage, msgStorage)
	assertErrorResponse(t, queryList(t, router, boundaryRepo),
		http.StatusServiceUnavailable, codeStorage, msgStorage)
